import React, { useState, useEffect } from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  IconButton,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  Tab,
  Tabs,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
} from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import {
  getRegulationCategories,
  createRegulationCategory,
  updateRegulationCategory,
  deleteRegulationCategory,
  getRegulations,
  createRegulation,
  updateRegulation,
  deleteRegulation
} from '../services/api';

function RegulationsPage() {
  const [activeTab, setActiveTab] = useState(0);
  const [categories, setCategories] = useState([]);
  const [regulations, setRegulations] = useState([]);
  const [openCategoryDialog, setOpenCategoryDialog] = useState(false);
  const [openRegulationDialog, setOpenRegulationDialog] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);
  const [formData, setFormData] = useState({
    name: '',
    subCategories: [],
    title: '',
    category: '',
    subCategory: '',
    documentUrl: '',
    year: new Date().getFullYear(),
    order: 0,
  });
  const [newSubCategory, setNewSubCategory] = useState('');
  const [file, setFile] = useState(null);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [categories, regulations] = await Promise.all([
        getRegulationCategories(),
        getRegulations()
      ]);
      setCategories(categories);
      setRegulations(regulations);
    } catch (error) {
      console.error('Error fetching data:', error);
    }
  };

  const handleTabChange = (event, newValue) => {
    setActiveTab(newValue);
  };

  const handleOpenDialog = (type, item = null) => {
    if (type === 'category') {
      setOpenCategoryDialog(true);
    } else {
      setOpenRegulationDialog(true);
    }
    setSelectedItem(item);
    if (item) {
      // For editing existing category
      if (type === 'category') {
        setFormData({
          name: item.name,
          subCategories: Array.isArray(item.subCategories) ? item.subCategories : [],
          order: item.order || 0
        });
      } else {
        // For editing existing regulation
        setFormData({
          title: item.title,
          categoryId: item.categoryId,
          subCategory: item.subCategory,
          documentUrl: item.documentUrl,
          year: item.year,
          order: item.order || 0
        });
      }
    } else {
      // For adding new item
      if (type === 'category') {
        setFormData({
          name: '',
          subCategories: [],
          order: 0
        });
      } else {
        setFormData({
          title: '',
          categoryId: '',
          subCategory: '',
          documentUrl: '',
          year: new Date().getFullYear(),
          order: 0
        });
      }
    }
  };

  const handleCloseDialog = () => {
    setOpenCategoryDialog(false);
    setOpenRegulationDialog(false);
    setSelectedItem(null);
    setFile(null);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleSubmit = async (type) => {
    try {
      if (type === 'category') {
        const categoryData = {
          name: formData.name,
          subCategories: formData.subCategories,
          order: formData.order
        };
        if (selectedItem) {
          await updateRegulationCategory(selectedItem.id, categoryData);
        } else {
          await createRegulationCategory(categoryData);
        }
      } else {
        const formDataObj = new FormData();
        Object.keys(formData).forEach(key => {
          formDataObj.append(key, formData[key]);
        });
        if (file) {
          formDataObj.append('document', file);
        }
        
        if (selectedItem) {
          await updateRegulation(selectedItem._id, formDataObj);
        } else {
          await createRegulation(formDataObj);
        }
      }
      
      fetchData();
      handleCloseDialog();
    } catch (error) {
      console.error('Error submitting form:', error);
    }
  };

  const handleDelete = async (type, id) => {
    if (!window.confirm('Are you sure you want to delete this item?')) return;
    
    try {
      if (type === 'categories') {
        await deleteRegulationCategory(id);
      } else {
        await deleteRegulation(id);
      }
      fetchData();
    } catch (error) {
      console.error('Error deleting item:', error);
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" sx={{ mb: 3 }}>
        Manage Regulations
      </Typography>

      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
        <Tabs value={activeTab} onChange={handleTabChange}>
          <Tab label="Categories" />
          <Tab label="Regulations" />
        </Tabs>
      </Box>

      {activeTab === 0 && (
        <>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => handleOpenDialog('category')}
            sx={{ mb: 3 }}
          >
            Add Category
          </Button>

          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Name</TableCell>
                  <TableCell>Sub Categories</TableCell>
                  <TableCell>Order</TableCell>
                  <TableCell>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {categories.map((category) => (
                  <TableRow key={category.id}>
                    <TableCell>{category.name}</TableCell>
                    <TableCell>
                      {Array.isArray(category.subCategories) ? category.subCategories.map(sub => sub.name).join(', ') : ''}
                    </TableCell>
                    <TableCell>{category.order}</TableCell>
                    <TableCell>
                      <IconButton onClick={() => handleOpenDialog('category', category)}>
                        <EditIcon />
                      </IconButton>
                      <IconButton onClick={() => handleDelete('categories', category.id)}>
                        <DeleteIcon />
                      </IconButton>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </>
      )}

      {activeTab === 1 && (
        <>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => handleOpenDialog('regulation')}
            sx={{ mb: 3 }}
          >
            Add Regulation
          </Button>

          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Title</TableCell>
                  <TableCell>Category</TableCell>
                  <TableCell>Sub Category</TableCell>
                  <TableCell>Year</TableCell>
                  <TableCell>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {regulations.map((regulation) => (
                  <TableRow key={regulation.id}>
                    <TableCell>{regulation.title}</TableCell>
                    <TableCell>{regulation.category?.name}</TableCell>
                    <TableCell>{regulation.subCategory}</TableCell>
                    <TableCell>{regulation.year}</TableCell>
                    <TableCell>
                      <IconButton onClick={() => handleOpenDialog('regulation', regulation)}>
                        <EditIcon />
                      </IconButton>
                      <IconButton onClick={() => handleDelete('regulations', regulation.id)}>
                        <DeleteIcon />
                      </IconButton>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </>
      )}

      {/* Category Dialog */}
      <Dialog open={openCategoryDialog} onClose={handleCloseDialog} maxWidth="sm" fullWidth>
        <DialogTitle>
          {selectedItem ? 'Edit Category' : 'Add Category'}
        </DialogTitle>
        <DialogContent>
          <TextField
            name="name"
            label="Category Name"
            value={formData.name}
            onChange={handleInputChange}
            fullWidth
            margin="normal"
          />
          <TextField
            name="order"
            label="Display Order"
            type="number"
            value={formData.order}
            onChange={handleInputChange}
            fullWidth
            margin="normal"
          />
          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle1">Sub Categories</Typography>
            <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
              <TextField
                value={newSubCategory}
                onChange={(e) => setNewSubCategory(e.target.value)}
                placeholder="New sub category"
                size="small"
              />
              <Button
                variant="contained"
                onClick={() => {
                  if (newSubCategory.trim()) {
                    setFormData(prev => ({
                      ...prev,
                      subCategories: [...prev.subCategories, { name: newSubCategory.trim() }]
                    }));
                    setNewSubCategory('');
                  }
                }}
              >
                Add
              </Button>
            </Box>
            {Array.isArray(formData.subCategories) && formData.subCategories.map((sub, index) => (
              <Box key={index} sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                <Typography>{sub.name}</Typography>
                <IconButton
                  size="small"
                  onClick={() => {
                    setFormData(prev => ({
                      ...prev,
                      subCategories: prev.subCategories.filter((_, i) => i !== index)
                    }));
                  }}
                >
                  <DeleteIcon />
                </IconButton>
              </Box>
            ))}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>Cancel</Button>
          <Button onClick={() => handleSubmit('category')} variant="contained">
            {selectedItem ? 'Update' : 'Add'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Regulation Dialog */}
      <Dialog open={openRegulationDialog} onClose={handleCloseDialog} maxWidth="sm" fullWidth>
        <DialogTitle>
          {selectedItem ? 'Edit Regulation' : 'Add Regulation'}
        </DialogTitle>
        <DialogContent>
          <TextField
            name="title"
            label="Title"
            value={formData.title}
            onChange={handleInputChange}
            fullWidth
            margin="normal"
          />
          <FormControl fullWidth margin="normal">
            <InputLabel>Category</InputLabel>
            <Select
              name="categoryId"
              value={formData.categoryId}
              onChange={handleInputChange}
            >
              {categories.map((category) => (
                <MenuItem key={category.id} value={category.id}>
                  {category.name}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <FormControl fullWidth margin="normal">
            <InputLabel>Sub Category</InputLabel>
            <Select
              name="subCategory"
              value={formData.subCategory}
              onChange={handleInputChange}
            >
              {categories
                .find(cat => cat.id === formData.categoryId)
                ?.subCategories?.map((sub, index) => (
                  <MenuItem key={index} value={sub.name}>
                    {sub.name}
                  </MenuItem>
                )) || []}
            </Select>
          </FormControl>
          <TextField
            name="year"
            label="Year"
            type="number"
            value={formData.year}
            onChange={handleInputChange}
            fullWidth
            margin="normal"
          />
          <TextField
            name="order"
            label="Display Order"
            type="number"
            value={formData.order}
            onChange={handleInputChange}
            fullWidth
            margin="normal"
          />
          <input
            type="file"
            accept=".pdf"
            onChange={handleFileChange}
            style={{ marginTop: 16 }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>Cancel</Button>
          <Button onClick={() => handleSubmit('regulation')} variant="contained">
            {selectedItem ? 'Update' : 'Add'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

export default RegulationsPage;
