import React, { useState, useEffect, forwardRef, useImperativeHandle } from 'react';
import { getNewsItems, deleteNewsItem } from '../../services/api';
import { Table, Button, Space, Image, message, Typography } from 'antd';
import { EditOutlined, DeleteOutlined } from '@ant-design/icons';
import moment from 'moment';
import { useWindowSize } from '../../hooks/useWindowSize';

const NewsList = forwardRef(function NewsList({ onEdit }, ref) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const { width } = useWindowSize();

  const fetchNews = async () => {
    setLoading(true);
    try {
      const data = await getNewsItems();
      setItems(data);
    } catch (error) {
      message.error('Failed to fetch news items');
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchNews();
  }, []);

  useImperativeHandle(ref, () => ({
    refresh: fetchNews
  }));

  const handleDelete = async (id) => {
    try {
      await deleteNewsItem(id);
      message.success('News item deleted successfully');
      fetchNews();
    } catch (error) {
      message.error('Failed to delete news item');
    }
  };

  const getColumns = () => {
    const baseColumns = [
      {
        title: 'Image',
        dataIndex: 'imageUrl',
        key: 'imageUrl',
        width: width < 768 ? 80 : 120,
        render: (imageUrl) => (
          <Image
            src={imageUrl}
            alt="News"
            width={width < 768 ? 60 : 100}
            height={width < 768 ? 60 : 100}
            style={{ objectFit: 'cover' }}
          />
        ),
      },
      {
        title: 'Title',
        dataIndex: 'title',
        key: 'title',
        width: width < 768 ? 120 : 220,
        render: (text) => (
          <Typography.Paragraph
            ellipsis={{ rows: width < 768 ? 1 : 2, tooltip: text }}
            style={{ marginBottom: 0, whiteSpace: 'normal', wordBreak: 'break-word' }}
          >
            {text}
          </Typography.Paragraph>
        ),
      },
      {
        title: 'Date',
        dataIndex: 'date',
        key: 'date',
        width: width < 768 ? 90 : 120,
        render: (date) => moment(date).format(width < 768 ? 'MM/DD/YY' : 'YYYY-MM-DD'),
        sorter: (a, b) => moment(a.date).unix() - moment(b.date).unix(),
      },
      {
        title: 'Actions',
        key: 'actions',
        width: width < 768 ? 100 : 200,
        render: (_, record) => (
          <Space>
            <Button
              type="primary"
              icon={<EditOutlined />}
              onClick={() => onEdit(record)}
              size={width < 768 ? 'small' : 'middle'}
            >
              {width >= 768 && 'Edit'}
            </Button>
            <Button
              type="primary"
              danger
              icon={<DeleteOutlined />}
              onClick={() => handleDelete(record.id)}
              size={width < 768 ? 'small' : 'middle'}
            >
              {width >= 768 && 'Delete'}
            </Button>
          </Space>
        ),
      },
    ];

    // Add content column only for desktop view
    if (width >= 768) {
      baseColumns.splice(3, 0, {
        title: 'Content',
        dataIndex: 'content',
        key: 'content',
        width: 360,
        render: (text) => (
          <Typography.Paragraph
            ellipsis={{ rows: 2, tooltip: text }}
            style={{ marginBottom: 0, whiteSpace: 'normal', wordBreak: 'break-word' }}
          >
            {text}
          </Typography.Paragraph>
        ),
      });
    }

    return baseColumns;
  };

  return (
    <Table
      columns={getColumns()}
      dataSource={items}
      rowKey="id"
      loading={loading}
      scroll={{ x: true }}
      pagination={{
        responsive: true,
        position: width < 768 ? ['bottomCenter'] : ['bottomRight'],
        size: width < 768 ? 'small' : 'default',
        pageSize: width < 768 ? 5 : 10
      }}
      size={width < 768 ? 'small' : 'middle'}
    />
  );
});

export default NewsList;
