import React, { useEffect, useState } from 'react';
import { Form, Input, Button, message, Upload, InputNumber } from 'antd';
import { UploadOutlined } from '@ant-design/icons';
import { createGalleryItem, updateGalleryItem } from '../../services/api';

const GalleryForm = ({ initialValues, onSuccess, onCancel }) => {
  const [form] = Form.useForm();
  const [fileList, setFileList] = useState([]);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    if (initialValues) {
      form.setFieldsValue(initialValues);
      if (initialValues.imageUrl) {
        // Handle both relative and absolute URLs
        const imageUrl = initialValues.imageUrl.startsWith('http') 
          ? initialValues.imageUrl 
          : `${process.env.REACT_APP_API_URL}${initialValues.imageUrl}`;

        setFileList([{
          uid: '-1',
          name: 'Current Image',
          status: 'done',
          url: imageUrl,
        }]);
      }
    }
  }, [initialValues, form]);

  const onFinish = async (values) => {
    try {
      setUploading(true);

      // Validate file for new items
      if (!initialValues?.id && !fileList[0]) {
        message.error('Please select an image file');
        setUploading(false);
        return;
      }

      const formData = new FormData();

      // Append file first if it exists
      // Handle file upload
      const file = fileList[0];
      if (file?.originFileObj) {
        formData.append('image', file.originFileObj, file.originFileObj.name);
      } else if (file && !file.url && !file.preview) {
        formData.append('image', file);
      }

      // Then append other fields
      formData.append('title', values.title);
      formData.append('description', values.description || '');
      formData.append('category', values.category || '');
      formData.append('order', values.order || 0);

      // Log formData contents
      for (let [key, value] of formData.entries()) {
        console.log('FormData entry:', key, value);
      }

      if (initialValues?.id) {
        await updateGalleryItem(initialValues.id, formData);
        message.success('Gallery item updated successfully');
      } else {
        await createGalleryItem(formData);
        message.success('Gallery item created successfully');
      }
      form.resetFields();
      setFileList([]);
      onSuccess();
    } catch (error) {
      console.error('Error:', error);
      message.error(error.response?.data?.message || 'Failed to save gallery item');
    } finally {
      setUploading(false);
    }
  };

  const uploadProps = {
    onRemove: () => {
      setFileList([]);
    },
    beforeUpload: (file) => {
      if (!file.type.startsWith('image/')) {
        message.error('You can only upload image files!');
        return false;
      }
      const isLt5M = file.size / 1024 / 1024 < 5;
      if (!isLt5M) {
        message.error('Image must be smaller than 5MB!');
        return false;
      }
      const newFile = {
        originFileObj: file,
        name: file.name,
        status: 'done',
        uid: Date.now(),
        type: file.type
      };
      setFileList([newFile]);
      return false;
    },
    fileList,
  };

  return (
    <Form
      form={form}
      layout="vertical"
      onFinish={onFinish}
      encType="multipart/form-data"
    >
      <Form.Item
        name="title"
        label="Title"
        rules={[{ required: true, message: 'Please input title!' }]}
      >
        <Input />
      </Form.Item>

      <Form.Item
        name="description"
        label="Description"
      >
        <Input.TextArea rows={4} />
      </Form.Item>

      <Form.Item
        label="Image"
        required
        rules={[{
          validator: () => {
            if (!fileList[0] && !initialValues?.imageUrl) {
              return Promise.reject('Please upload an image!');
            }
            return Promise.resolve();
          }
        }]}
      >
        <Upload {...uploadProps} listType="picture" maxCount={1}>
          <Button icon={<UploadOutlined />}>Select Image</Button>
        </Upload>
      </Form.Item>

      <Form.Item
        name="category"
        label="Folder"
        rules={[{ required: true, message: 'Please input folder!' }]}
      >
        <Input />
      </Form.Item>

      <Form.Item
        name="order"
        label="Display Order"
        rules={[{ required: true, message: 'Please input display order!' }]}
      >
        <InputNumber min={0} />
      </Form.Item>

      <Form.Item>
        <Button type="primary" htmlType="submit">
          {initialValues?.id ? 'Update' : 'Create'}
        </Button>
        <Button onClick={onCancel} style={{ marginLeft: 8 }}>
          Cancel
        </Button>
      </Form.Item>
    </Form>
  );
};

export default GalleryForm;
