import React, { useState, useEffect } from 'react';
import { Card, message } from 'antd';
import { getAllWhatIsGymkhana } from '../services/api';
import WhatIsGymkhanaForm from '../components/whatIsGymkhana/WhatIsGymkhanaForm';

const WhatIsGymkhanaPage = () => {
  const [content, setContent] = useState(null);
  const [loading, setLoading] = useState(true);

  const fetchContent = async () => {
    setLoading(true);
    try {
      const data = await getAllWhatIsGymkhana();
      if (!data) {
        setContent(null);
        return;
      }
      if (!Array.isArray(data)) {
        setContent(data);
        return;
      }
      setContent(data.length > 0 ? data[0] : null);
    } catch (error) {
      console.error('Failed to fetch content:', error);
      message.error(`Failed to fetch content: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchContent();
  }, []);

  const handleSuccess = () => {
    fetchContent();
    message.success('Content saved successfully');
  };

  return (
    <Card
      title="What is Gymkhana Content"
      loading={loading}
    >
      <WhatIsGymkhanaForm
        initialValues={content}
        onSuccess={handleSuccess}
      />
    </Card>
  );
};

export default WhatIsGymkhanaPage;
