import React, { useEffect, useState } from 'react';
import { Card, Form, InputNumber, Button, message, Row, Col } from 'antd';
import { getChampionshipStats, updateChampionshipStats } from '../services/api';

const ChampionshipStatsPage = () => {
  const [form] = Form.useForm();
  const [loading, setLoading] = useState(false);

  const fetchStats = async () => {
    try {
      setLoading(true);
      const data = await getChampionshipStats();
      form.setFieldsValue({
        competitors: data.competitors || 0,
        countries: data.countries || 0,
        events: data.events || 0,
        champions: data.champions || 0,
      });
    } catch (e) {
      message.error('Failed to load championship stats');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStats();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onFinish = async (values) => {
    try {
      setLoading(true);
      await updateChampionshipStats(values);
      message.success('Championship statistics updated');
    } catch (e) {
      message.error('Failed to update championship statistics');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card title="Championship Statistics" bordered={false} loading={loading}>
      <Form
        form={form}
        layout="vertical"
        onFinish={onFinish}
        initialValues={{ competitors: 0, countries: 0, events: 0, champions: 0 }}
      >
        <Row gutter={16}>
          <Col xs={24} md={12} lg={6}>
            <Form.Item name="competitors" label="Competitors" rules={[{ required: true, message: 'Required' }]}> 
              <InputNumber min={0} style={{ width: '100%' }} />
            </Form.Item>
          </Col>
          <Col xs={24} md={12} lg={6}>
            <Form.Item name="countries" label="Countries" rules={[{ required: true, message: 'Required' }]}> 
              <InputNumber min={0} style={{ width: '100%' }} />
            </Form.Item>
          </Col>
          <Col xs={24} md={12} lg={6}>
            <Form.Item name="events" label="Events" rules={[{ required: true, message: 'Required' }]}> 
              <InputNumber min={0} style={{ width: '100%' }} />
            </Form.Item>
          </Col>
          <Col xs={24} md={12} lg={6}>
            <Form.Item name="champions" label="Champions" rules={[{ required: true, message: 'Required' }]}> 
              <InputNumber min={0} style={{ width: '100%' }} />
            </Form.Item>
          </Col>
        </Row>
        <Form.Item>
          <Button type="primary" htmlType="submit" loading={loading}>Save</Button>
        </Form.Item>
      </Form>
    </Card>
  );
};

export default ChampionshipStatsPage;
