import React, { useState, useEffect, forwardRef, useImperativeHandle } from 'react';
import { getGalleryItems, deleteGalleryItem } from '../../services/api';
import { Table, Button, Space, Image, message } from 'antd';
import { EditOutlined, DeleteOutlined } from '@ant-design/icons';

const GalleryList = forwardRef(function GalleryList({ onEdit }, ref) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);

  const fetchGalleryItems = async () => {
    setLoading(true);
    try {
      const data = await getGalleryItems();
      setItems(data);
    } catch (error) {
      message.error('Failed to fetch gallery items');
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchGalleryItems();
  }, []);

  useImperativeHandle(ref, () => ({
    refresh: fetchGalleryItems
  }));

  const handleDelete = async (id) => {
    try {
      await deleteGalleryItem(id);
      message.success('Gallery item deleted successfully');
      fetchGalleryItems();
    } catch (error) {
      message.error('Failed to delete gallery item');
    }
  };

  const columns = [
    {
      title: 'Image',
      dataIndex: 'imageUrl',
      key: 'imageUrl',
      render: (imageUrl) => (
        <Image
          src={imageUrl}
          alt="Gallery item"
          width={100}
          height={100}
          style={{ objectFit: 'cover' }}
        />
      ),
    },
    {
      title: 'Title',
      dataIndex: 'title',
      key: 'title',
    },
    {
      title: 'Folder',
      dataIndex: 'category',
      key: 'category',
    },
    {
      title: 'Order',
      dataIndex: 'order',
      key: 'order',
      sorter: (a, b) => a.order - b.order,
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, record) => (
        <Space>
          <Button
            type="primary"
            icon={<EditOutlined />}
            onClick={() => onEdit(record)}
          >
            Edit
          </Button>
          <Button
            type="primary"
            danger
            icon={<DeleteOutlined />}
            onClick={() => handleDelete(record.id)}
          >
            Delete
          </Button>
        </Space>
      ),
    },
  ];

  return (
    <Table
      columns={columns}
      dataSource={items}
      rowKey="id"
      loading={loading}
    />
  );
});

export default GalleryList;
