import React from 'react';
import { Form, Input, Button, Typography, Space, message } from 'antd';
import { updateContact, createContact } from '../../services/api';

const { TextArea } = Input;
const { Title } = Typography;

const ContactForm = ({ initialValues, onSuccess }) => {
  const [form] = Form.useForm();
  const isEditing = Boolean(initialValues?.id);

  React.useEffect(() => {
    form.resetFields();
    if (initialValues) {
      const formattedValues = {
        ...initialValues,
        socialMedia: initialValues.socialMedia ? JSON.parse(initialValues.socialMedia) : {}
      };
      form.setFieldsValue(formattedValues);
    }
  }, [initialValues, form]);

  const onFinish = async (values) => {
    try {
      const dataToSubmit = {
        ...values,
        socialMedia: JSON.stringify(values.socialMedia || {})
      };

      if (isEditing) {
        await updateContact(initialValues.id, dataToSubmit);
        message.success('Contact updated successfully');
      } else {
        await createContact(dataToSubmit);
        message.success('Contact created successfully');
      }
      onSuccess();
    } catch (error) {
      message.error(`Failed to ${isEditing ? 'update' : 'create'} contact`);
    }
  };

  return (
    <div style={{ maxWidth: 800, margin: '0 auto' }}>
      <Space direction="vertical" size="large" style={{ width: '100%' }}>
        <Form
          form={form}
          layout="vertical"
          onFinish={onFinish}
          initialValues={{
            email: '',
            phone: '',
            address: '',
            socialMedia: {},
            mapLocation: '',
            map: '',
            mapUrl: '',
            locationMap: '',
            googleMap: ''
          }}
        >
          <Form.Item
            name="email"
            label="Email"
            rules={[
              { required: true, message: 'Please enter email' },
              { type: 'email', message: 'Please enter a valid email' }
            ]}
          >
            <Input placeholder="Enter email" />
          </Form.Item>

          <Form.Item
            name="phone"
            label="Phone"
            rules={[{ required: true, message: 'Please enter phone number' }]}
          >
            <Input placeholder="Enter phone number" />
          </Form.Item>

          <Form.Item
            name="address"
            label="Address"
            rules={[{ required: true, message: 'Please enter address' }]}
          >
            <TextArea
              rows={4}
              placeholder="Enter address"
              style={{ resize: 'vertical' }}
            />
          </Form.Item>

          <Form.Item
            name={['socialMedia', 'facebook']}
            label="Facebook URL"
          >
            <Input placeholder="Enter Facebook URL" />
          </Form.Item>

          <Form.Item
            name={['socialMedia', 'twitter']}
            label="Twitter URL"
          >
            <Input placeholder="Enter Twitter URL" />
          </Form.Item>

          <Form.Item
            name={['socialMedia', 'instagram']}
            label="Instagram URL"
          >
            <Input placeholder="Enter Instagram URL" />
          </Form.Item>

          <Form.Item
            name={['socialMedia', 'youtube']}
            label="YouTube URL"
          >
            <Input placeholder="Enter YouTube URL" />
          </Form.Item>

          <Form.Item
            name="mapLocation"
            label="Map Location (Embed URL)"
          >
            <TextArea
              rows={4}
              placeholder="Enter Google Maps embed URL"
              style={{ resize: 'vertical' }}
            />
          </Form.Item>

          <Form.Item
            name="map"
            label="Map (URL or Address)"
          >
            <TextArea
              rows={2}
              placeholder="Enter Google Maps link or plain address"
              style={{ resize: 'vertical' }}
            />
          </Form.Item>

          <Form.Item
            name="mapUrl"
            label="Map URL (URL or Address)"
          >
            <TextArea
              rows={2}
              placeholder="Enter Google Maps link or plain address"
              style={{ resize: 'vertical' }}
            />
          </Form.Item>

          <Form.Item
            name="locationMap"
            label="Location Map (URL or Address)"
          >
            <TextArea
              rows={2}
              placeholder="Enter Google Maps link or plain address"
              style={{ resize: 'vertical' }}
            />
          </Form.Item>

          <Form.Item
            name="googleMap"
            label="Google Map (URL or Address)"
          >
            <TextArea
              rows={2}
              placeholder="Enter Google Maps link or plain address"
              style={{ resize: 'vertical' }}
            />
          </Form.Item>

          <Form.Item>
            <Button type="primary" htmlType="submit">
              {isEditing ? 'Update Contact' : 'Create Contact'}
            </Button>
          </Form.Item>
        </Form>
      </Space>
    </div>
  );
};

export default ContactForm;
